function minDeletion(nums) {
  let kept = 0;
  let last = -1;

  for (const value of nums) {
    if (kept % 2 === 1 && value === last) {
      continue;
    }
    last = value;
    kept++;
  }
  if (kept % 2 === 1) {
    kept--;
  }
  return nums.length - kept;
}

