function minDeletion(nums) {
  // Longest beautiful subsequence by exhaustive search with memo:
  // state (i, open) means elements before i are decided and open is the index of an unpaired kept element, or -1.
  const n = nums.length;
  const memo = new Map();
  const longest = (i, open) => {
    if (i === n) return open === -1 ? 0 : -Infinity;
    const key = i * (n + 1) + open + 1;
    if (memo.has(key)) return memo.get(key);
    let best = longest(i + 1, open);
    if (open === -1) best = Math.max(best, longest(i + 1, i));
    else if (nums[i] !== nums[open]) best = Math.max(best, 2 + longest(i + 1, -1));
    memo.set(key, best);
    return best;
  };
  return n - longest(0, -1);
}

