function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const top = pick(0, 3);
    return [Array.from({ length: n }, () => pick(0, top))];
  }
  const n = 2000;
  const top = [1, 2, 5, 100000][pick(0, 3)];
  const nums = [];
  // Runs of repeated values make the greedy delete often.
  while (nums.length < n) {
    const value = pick(0, top);
    const run = pick(1, 4);
    for (let i = 0; i < run && nums.length < n; i++) nums.push(value);
  }
  return [nums];
}
